package com.codekatha.machinecodingpractice.mine.dsaquest.firstphase.set01_hashing;

import com.codekatha.machinecodingpractice.mine.dsaquest.common.Check;

/**
 * LeetCode #389 - Find the Difference  [Easy]
 * Link   : https://leetcode.com/problems/find-the-difference/
 * Pattern: Hash Map / Set / Counting
 * <p>
 * You are given two strings s and t. String t is generated by random shuffling string s and
 * then adding one more letter at a random position. Return the letter that was added to t.
 * <p>
 * Example 1:
 * <pre>
 * Input: s = "abcd", t = "abcde"
 * Output: "e"
 * </pre>
 * <p>
 * Example 2:
 * <pre>
 * Input: s = "", t = "y"
 * Output: "y"
 * </pre>
 * <p>
 * Constraints:
 * - 0 <= s.length <= 1000
 * - t.length == s.length + 1
 * - s and t consist of lowercase English letters.
 * <p>
 * Hint (spoiler - pehle khud try karo): Count diff se ho jayega; XOR / char-sum se O(1) space me bhi.
 */
public class LC0389_FindTheDifference {

    // TODO: apna solution yahan likho
    public char findTheDifference(String s, String t) {

        int[] freqData = new int[26];

        for (int i = 0; i < s.length(); i++) {
            int idx = s.charAt(i) - 'a';
            freqData[idx]++;
        }

        for (int i = 0; i < t.length(); i++) {
            char ch = t.charAt(i);
            int idx = ch - 'a';
            //System.out.println("getting ch: "+ch+", idx: "+idx+",freqData[idx]: "+freqData[idx]);
            if(freqData[idx]==0){
                return ch;
            }
            freqData[idx]--;
        }

        return ' ';
    }

//    Approach A (count): s ka freq banao, t me chalte hue jahan freq 0 mile wahi extra hai.
//    Approach B (XOR, bonus): saare chars ko XOR karte jao, s ke bhi aur t ke bhi.
//    Jo letters pair me aate hain wo a ^ a = 0 se cancel ho jate hain, aur extra akela bachta ha
//
//    char res = 0;
//    for (char c : s.toCharArray()) res ^= c;
//    for (char c : t.toCharArray()) res ^= c;
//    return res;

    public static void main(String[] args) {
        LC0389_FindTheDifference sol = new LC0389_FindTheDifference();
        Check.start("LC0389_FindTheDifference");
        Check.eq("e", () -> sol.findTheDifference("abcd", "abcde"));
        Check.eq("y", () -> sol.findTheDifference("", "y"));
        Check.summary();
    }
}
